solutions.naive:
class Solution:
    def minimumTime(self, time: list[int], totalTrips: int) -> int:
        t = 1
        while True:
            trips = 0
            for bus in time:
                trips += t // bus
            if trips >= totalTrips:
                return t
            t += 1

solutions.better:
class Solution:
    def minimumTime(self, time: list[int], totalTrips: int) -> int:
        lo, hi = 1, min(time) * totalTrips
        while lo < hi:
            mid = (lo + hi) // 2
            trips = sum(mid // bus for bus in time)
            if trips >= totalTrips:
                hi = mid
            else:
                lo = mid + 1
        return lo

